module idea_cfb64
fn mul16(a u16,b u16)u16{x:=if a==0{u64(65536)}else{u64(a)};y:=if b==0{u64(65536)}else{u64(b)};z:=(x*y)%u64(65537);return if z==65536{u16(0)}else{u16(z)}}
fn add16(a u16,b u16)u16{return u16((u32(a)+u32(b))&u32(65535))}
fn expand(key [16]u8)[52]u16{mut state:=[8]u16{};for i in 0..8{state[i]=(u16(key[2*i])<<8)|u16(key[2*i+1])};mut z:=[52]u16{};mut off:=0;for off<52{count:=if 52-off<8{52-off}else{8};for i in 0..count{z[off+i]=state[i]};mut rotated:=[8]u16{};for i in 0..8{rotated[i]=u16((u32(state[(i+1)&7])<<9)|(u32(state[(i+2)&7])>>7))};state=rotated;off+=8};return z}
fn encrypt(z [52]u16,input [8]u8)[8]u8{mut x1:=(u16(input[0])<<8)|u16(input[1]);mut x2:=(u16(input[2])<<8)|u16(input[3]);mut x3:=(u16(input[4])<<8)|u16(input[5]);mut x4:=(u16(input[6])<<8)|u16(input[7]);for r in 0..8{k:=r*6;a:=mul16(x1,z[k]);b:=add16(x2,z[k+1]);c:=add16(x3,z[k+2]);d:=mul16(x4,z[k+3]);p:=mul16(a^c,z[k+4]);q:=mul16(add16(b^d,p),z[k+5]);t:=add16(p,q);x1=a^q;x2=c^q;x3=b^t;x4=d^t};words:=[4]u16{mul16(x1,z[48]),add16(x3,z[49]),add16(x2,z[50]),mul16(x4,z[51])};mut out:=[8]u8{};for i in 0..4{out[2*i]=u8(words[i]>>8);out[2*i+1]=u8(words[i]&255)};return out}
fn put(out &u8,data [24]u8,n int){for i in 0..n{unsafe{out[i]=data[i]}}}
@[export:'idea_cfb64']
pub fn idea_cfb64(raw &i64,n usize,out &u8,cap usize)i64{unsafe{if raw==nil||n<27||n>51{return -1};mode:=raw[0];lv:=raw[1];if mode<0||mode>1||lv<1||lv>24||int(n)!=26+int(lv){return -1};len:=int(lv);mut key:=[16]u8{};mut state:=[8]u8{};mut text:=[24]u8{};mut result:=[24]u8{};for i in 0..16{if raw[2+i]<0||raw[2+i]>255{return -1};key[i]=u8(raw[2+i])};for i in 0..8{if raw[18+i]<0||raw[18+i]>255{return -1};state[i]=u8(raw[18+i])};for i in 0..len{if raw[26+i]<0||raw[26+i]>255{return -1};text[i]=u8(raw[26+i])};z:=expand(key);mut pos:=0;for pos<len{stream:=encrypt(z,state);take:=if len-pos<8{len-pos}else{8};for j in 0..take{result[pos+j]=text[pos+j]^stream[j];state[j]=if mode==0{result[pos+j]}else{text[pos+j]}};pos+=take};if out==nil||cap<len{return -2};put(out,result,len);return i64(len)}}
